import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const STATUSES = ['신청', '승인', '반려'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function parseId(value: string | undefined): string {
  if (!value || !/^\d{1,18}$/.test(value)) {
    throw new ApiError(404, 'CERTIFICATE_NOT_FOUND', '신청 건을 찾을 수 없습니다.');
  }
  return value;
}

function numberOf(value: unknown, fallback: number, min: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(String(value));
  if (!Number.isInteger(n) || n < min) {
    throw new ApiError(400, 'VALIDATION_FAILED', '요청 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr01603Controller {
  @Get('/certificates')
  async listCertificates(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const page = numberOf(q['page'], 0, 0);
    const size = Math.min(numberOf(q['size'], DEFAULT_SIZE, 1), MAX_SIZE);
    const rawStatus = q['status'];
    let status: string | null = null;
    if (rawStatus !== undefined && rawStatus !== null && rawStatus !== '') {
      status = String(rawStatus);
      if (!STATUSES.includes(status)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM certificate WHERE (CAST(:status AS text) IS NULL OR status = CAST(:status AS text))',
        { status },
      );
      const items = await db.query(
        'SELECT certificate_id AS "certificateId", certificate_form_id AS "certificateFormId", employee_id AS "employeeId", submission_to AS "submissionTo", copies AS "copies", status AS "status", certificate_no AS "certificateNo" '
          + 'FROM certificate WHERE (CAST(:status AS text) IS NULL OR status = CAST(:status AS text)) '
          + 'ORDER BY certificate_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { status, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/certificates/:certificateId/approve')
  @HttpCode(200)
  async approveCertificate(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = parseId(req.params['certificateId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT c.status AS "status", f.numbering_rule_id AS "numberingRuleId" '
          + 'FROM certificate c JOIN certificate_form f ON f.certificate_form_id = c.certificate_form_id '
          + 'WHERE c.certificate_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_NOT_FOUND', '신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태의 건만 승인할 수 있습니다.');
      }
      const ruleId = found[0]['numberingRuleId'];
      if (ruleId === null || ruleId === undefined) {
        throw new ApiError(422, 'NUMBERING_RULE_NOT_CONFIGURED', '증명서 양식에 연결된 채번 규칙이 없습니다.');
      }
      // 가정: 채번 규칙 테이블이 스펙에 없어 규칙ID-발급일-증명서ID 형식으로 번호를 만든다 (증명서ID로 중복 방지)
      const updated = await db.query(
        "UPDATE certificate SET status = '승인', "
          + "certificate_no = 'CERT-' || CAST(:ruleId AS text) || '-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(CAST(certificate_id AS text), 6, '0'), "
          + 'issued_date = CAST(now() AS date), updated_at = now() '
          + "WHERE certificate_id = CAST(:id AS bigint) AND status = '신청' "
          + 'RETURNING status AS "status", certificate_no AS "certificateNo"',
        { id, ruleId },
      );
      if (updated.length === 0) {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태의 건만 승인할 수 있습니다.');
      }
      return updated[0];
    });
  }

  @Post('/certificates/:certificateId/reject')
  @HttpCode(200)
  async rejectCertificate(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = parseId(req.params['certificateId']);
    const data = checks.inputOf(req.body);
    const raw = data['rejectReason'];
    const reason = typeof raw === 'string' ? raw.trim() : '';
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM certificate WHERE certificate_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_NOT_FOUND', '신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태의 건만 반려할 수 있습니다.');
      }
      if (reason === '') {
        throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
      }
      const updated = await db.query(
        "UPDATE certificate SET status = '반려', reject_reason = :reason, updated_at = now() "
          + "WHERE certificate_id = CAST(:id AS bigint) AND status = '신청' "
          + 'RETURNING status AS "status"',
        { id, reason },
      );
      if (updated.length === 0) {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태의 건만 반려할 수 있습니다.');
      }
      return updated[0];
    });
  }
}

