import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, TextInput, Select, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

type Action = { mode: 'approve' | 'reject'; row: Row };

export default function FnSfr01603Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [action, setAction] = useState<Action | null>(null);
  const [reason, setReason] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: applied, page: pageNo, size: 20 }),
    [applied, pageNo],
  );
  const waiting = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: '신청', page: 0, size: 5 }),
    [],
  );

  function refresh() {
    list.reload();
    waiting.reload();
  }

  function open(mode: 'approve' | 'reject', row: Row) {
    setReason('');
    setAction({ mode, row });
  }

  const columns: Column[] = [
    { key: 'certificateId', label: '증명서 ID' },
    {
      key: 'certificateFormId',
      label: '증명서 양식',
      render: (r) => <RefName table="certificate_form" role={role} value={r.certificateFormId} />,
    },
    {
      key: 'employeeId',
      label: '신청자',
      render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
    },
    { key: 'submissionTo', label: '제출처' },
    { key: 'copies', label: '발급 부수' },
    { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
    { key: 'certificateNo', label: '증명서 번호' },
    {
      key: 'action',
      label: '처리',
      render: (r) => (
        r.status === '신청' ? (
          <span>
            <button type="button" onClick={() => open('approve', r)}>승인</button>
            <button type="button" onClick={() => open('reject', r)}>반려</button>
          </span>
        ) : null
      ),
    },
  ];

  const waitingColumns: Column[] = [
    { key: 'certificateId', label: '증명서 ID' },
    {
      key: 'employeeId',
      label: '신청자',
      render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
    },
    { key: 'submissionTo', label: '제출처' },
  ];

  async function submit() {
    if (!action) {
      return;
    }
    const id = action.row.certificateId;
    if (action.mode === 'approve') {
      await call('POST', `/certificates/${id}/approve`, role);
      notify('승인했습니다.');
    } else {
      if (reason.trim() === '') {
        throw new Error('반려 사유를 입력해 주세요.');
      }
      await call('POST', `/certificates/${id}/reject`, role, { rejectReason: reason.trim() });
      notify('반려했습니다.');
    }
    setAction(null);
    refresh();
  }

  const rows = list.data ? list.data.items : [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리 대기', <Num2 key="w" value={waiting.data ? waiting.data.total : 0} />],
            ['조회 결과', <Num2 key="t" value={list.data ? list.data.total : 0} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>증명서 신청</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied(status);
          }}
          onReset={() => {
            setStatus('');
            setApplied('');
            setPageNo(0);
          }}
        >
          <Field label="상태">
            <Select
              value={status}
              onChange={setStatus}
              options={[['신청', '신청'], ['승인', '승인'], ['반려', '반려']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={list.data ? list.data.total : 0} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={rows} empty="신청 건이 없습니다." />
        <Pager
          page={list.data ? list.data.page : 0}
          size={list.data ? list.data.size : 20}
          total={list.data ? list.data.total : 0}
          onPage={setPageNo}
        />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          columns={waitingColumns}
          rows={waiting.data ? waiting.data.items : []}
          onRowClick={(r) => open('approve', r)}
          empty="대기 중인 신청이 없습니다."
        />
      </section>
      {action ? (
        <Drawer
          title={action.mode === 'approve' ? '증명서 신청 승인' : '증명서 신청 반려'}
          onClose={() => setAction(null)}
        >
          <Pairs
            items={[
              ['증명서 ID', String(action.row.certificateId)],
              ['증명서 양식', <RefName key="f" table="certificate_form" role={role} value={action.row.certificateFormId} />],
              ['신청자', <RefName key="e" table="employee" role={role} value={action.row.employeeId} />],
              ['제출처', String(action.row.submissionTo ?? '')],
              ['발급 부수', String(action.row.copies ?? '')],
              ['상태', <Badge key="s" value={action.row.status} />],
            ]}
          />
          <Form
            onSubmit={submit}
            submit={action.mode === 'approve' ? '승인' : '반려'}
            danger={action.mode === 'reject'}
            note={action.mode === 'approve' ? '승인하면 증명서 번호가 부여됩니다.' : undefined}
          >
            {action.mode === 'reject' ? (
              <Field label="반려 사유" required wide>
                <TextInput value={reason} onChange={setReason} multiline />
              </Field>
            ) : null}
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}

function Num2({ value }: { value: number }) {
  return <strong>{value.toLocaleString()}</strong>;
}
